const rl=require('readline').createInterface({input:process.stdin});
const out=o=>process.stdout.write(JSON.stringify(o)+"\n");
rl.on('line',l=>{let m;try{m=JSON.parse(l)}catch{return}
if(m.id===undefined)return;
if(m.method==='initialize')out({jsonrpc:'2.0',id:m.id,result:{protocolVersion:'2024-11-05',capabilities:{tools:{}},serverInfo:{name:'demo',version:'1.0.0'}}});
else if(m.method==='tools/list')out({jsonrpc:'2.0',id:m.id,result:{tools:[{name:'echo',description:'Echo text',inputSchema:{type:'object',properties:{text:{type:'string'}}}}]}});
else if(m.method==='tools/call')out({jsonrpc:'2.0',id:m.id,result:{content:[{type:'text',text:'echo:'+(m.params.arguments||{}).text}]}});
else out({jsonrpc:'2.0',id:m.id,error:{code:-32601,message:'nf'}});});
EOF
